function D(c,a){const s=c.length;if(s<3)return c.map((t,n)=>n);const o=a*a,r=new Uint8Array(s);r[0]=1,r[s-1]=1;const d=[[0,s-1]];for(;d.length;){const[t,n]=d.pop(),f=c[t][0],e=c[t][1],u=c[n][0],g=c[n][1],x=u-f,m=g-e,k=x*x+m*m;let I=0,h=-1;for(let l=t+1;l<n;l++){let q;if(k===0){const y=c[l][0]-f,S=c[l][1]-e;q=y*y+S*S}else{const y=((c[l][0]-f)*x+(c[l][1]-e)*m)/k,S=f+y*x,_=e+y*m,b=c[l][0]-S,w=c[l][1]-_;q=b*b+w*w}q>I&&(I=q,h=l)}I>o&&h>0&&(r[h]=1,d.push([t,h],[h,n]))}const i=[];for(let t=0;t<s;t++)r[t]&&i.push(t);return i}function A(c,a){const s=c.length;if(s<4)return c.map((e,u)=>u);let o=1,r=0;const d=c[0][0],i=c[0][1];for(let e=1;e<s;e++){const u=c[e][0]-d,g=c[e][1]-i,x=u*u+g*g;x>r&&(r=x,o=e)}const t=D(c.slice(0,o+1),a),n=D(c.slice(o),a),f=t.slice();for(let e=1;e<n.length;e++)f.push(o+n[e]);return f}export{D as douglasPeuckerIndices,A as simplifyRingIndices};
